  const _p = [0, 0, 0], _c = [0, 0, 0], _n = [0, 0, 0], UP = [0, 1, 0];
  const wipe = (f, x) => sstep(0, 0.18, f * 1.18 - (x / TW + 0.5));   // the sweep's share at x for a step's progress f
