    params: { map_a: 1, map_cell: 1, map_r: 50, map_balls: 0, map_bars: 1, map_score: 1, map_all: 0, map_split: 0, map_omics: 0, map_pick: -1, map_delta: 0 },
    update(S, t) { lastS = S; update(S, t); }, anchors, labels, cam, controls, explore,
    api: () => API,
