      Pk.Y[0] = -ly * Math.sin(th); Pk.Y[1] = ly * Math.cos(th); Pk.Y[2] = 0;
      big.add(H.phi[k], Pk.o, Pk.U, Pk.Y, 0.008, k ? GREEN : CYAN, shA, OPT_PHI[k]);
