  if (k === 'body') Object.assign(tg, { body_net: 0, body_state: 0, liver_a: 1, liver_lift: c.liver === 'in' ? 0 : 1, liver_slice: c.liver === 'slice' ? 0.42 : 0 });
  // the map lies on the slide's window (its explore() says how the slide shows under it)
